xql_query:
// ============================================================
// Rule: WIN_AD Multiple User Creations Sailpoint Error
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_AD Multiple User Creations Sailpoint Error.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0003 - Persistence
// Technique: T1136 - Create Account

config case_sensitive = false


// ========================================
// Fonte de dados: Cortex XDR
// Inclui Windows Security Event Log
// ========================================
| dataset = xdr_data


// ========================================
// Filtro de eventos:
// 4720 = User Account Created
// 4738 = User Account Changed (enriquecimento de atributos)
// ========================================
| filter event_type = ENUM.EVENT_LOG
| filter action_evtlog_event_id in (4720, 4738)


// ========================================
// Normalização dos campos relevantes
// ========================================
| alter
    EventID          = action_evtlog_event_id,                     // ID do evento (4720 / 4738)
    SamAccountName   = action_evtlog_data_fields -> SamAccountName, // Login do usuário
    AD_DisplayName   = action_evtlog_data_fields -> DisplayName,    // Nome completo no AD
    TargetDomainName = action_evtlog_data_fields -> TargetDomainName, // Domínio
    Endpoint         = action_evtlog_data_fields -> SubjectUserName // Conta que realizou a ação


// ========================================
// Filtro: somente criações vindas do SailPoint
// ========================================
| filter Endpoint = "<IDENTITY_PROVISIONING_ACCOUNT>"

| filter TargetDomainName != "<NON_PRODUCTION_DOMAIN>"

// ========================================
// Filtro de padrão no Nome do AD
// Retorna apenas usuários cujo DisplayName
// contenha a frase desejada
// ========================================
| filter AD_DisplayName contains "Contratado Nome"


// ========================================
// Agrupamento temporal
// Consolida eventos em janelas de 1 hora
// ========================================
| bin _time span = 1h


// ========================================
// Agregação:
// - Quantidade de usuários criados
// - sAMAccountNames criados
// - Names (DisplayName) associados
// - Eventos correlacionados (4720 / 4738)
// ========================================
| comp
    count_distinct(SamAccountName) as users_created,
    values(SamAccountName) as samaccount_created,
    values(AD_DisplayName) as ad_name_created,
    values(EventID) as related_events
  by _time, agent_hostname, Endpoint, TargetDomainName



// ========================================
// Ordenação para priorizar os maiores volumes
// ========================================
| sort desc users_created


// ========================================
// Saída final
// ========================================
| fields *
